import { test, expect } from '@playwright/test';

test.describe('Record Restoration - Archived Records', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/records');
  });

  test('should successfully restore an archived record', async ({ page }) => {
    // Verify archived records are visible
    const archivedRecordsList = page.getByRole('region', { name: /archived records/i });
    await expect(archivedRecordsList).toBeVisible();

    // Locate and click restore button on a specific archived record
    const restoreButton = page.getByRole('button', { name: /restore/i });
    await expect(restoreButton).toBeVisible();
    await restoreButton.click();

    // Verify restore confirmation modal appears
    const restoreModal = page.getByRole('dialog', { name: /restore record/i });
    await expect(restoreModal).toBeVisible();

    // Verify restore button is disabled in modal
    const restoreButtonModal = page.getByRole('button', { name: /restore/i });
    await expect(restoreButtonModal).toBeDisabled();

    // Verify restore button is enabled after successful restore
    const restoreButtonModalDisabled = page.getByRole('button', { name: /restore/i });
    await expect(restoreButtonModalDisabled).not.toBeDisabled();

    // Verify record is restored and visible
    const restoredRecord = page.getByText(/restored record/i);
    await expect(restoredRecord).toBeVisible();

    // Verify restore button is now disabled
    await expect(restoreButtonModalDisabled).toBeDisabled();

    // Verify restore button is not visible in archived records list
    await expect(restoreButtonModalDisabled).not.toBeVisible();

    // Verify restore button is visible in main records list
    const mainRecordsList = page.getByRole('region', { name: /records/i });
    await expect(mainRecordsList).toBeVisible();
    const restoreButtonMain = page.getByRole('button', { name: /restore/i });
    await expect(restoreButtonMain).toBeVisible();
  });

  test('should handle restore failure and display error message', async ({ page }) => {
    // Locate and click restore button on an archived record
    const restoreButton = page.getByRole('button', { name: /restore/i });
    await expect(restoreButton).toBeVisible();
    await restoreButton.click();

    // Verify restore confirmation modal appears
    const restoreModal = page.getByRole('dialog', { name: /restore record/i });
    await expect(restoreModal).toBeVisible();

    // Verify restore button is disabled in modal
    const restoreButtonModal = page.getByRole('button', { name: /restore/i });
    await expect(restoreButtonModal).toBeDisabled();

    // Verify error message is displayed
    const errorMessage = page.getByText(/restore failed/i);
    await expect(errorMessage).toBeVisible();

    // Verify restore button is still disabled
    await expect(restoreButtonModal).toBeDisabled();

    // Verify restore button is visible in main records list
    const mainRecordsList = page.getByRole('region', { name: /records/i });
    await expect(mainRecordsList).toBeVisible();
    const restoreButtonMain = page.getByRole('button', { name: /restore/i });
    await expect(restoreButtonMain).toBeVisible();
  });
});
